package com.aegis.erp.modules.planilla.cuentabancaria;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.aegis.erp.common.export.DocumentExportService;import com.aegis.erp.modules.planilla.entity.*;import com.aegis.erp.modules.planilla.repository.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;
@ExtendWith(MockitoExtension.class)class CuentaBancariaServiceTest{@Mock CuentaBancariaEmpleadoRepository cuentas;@Mock EmpleadoRepository empleados;@Mock BancoRepository bancos;@Mock DocumentExportService exports;CuentaBancariaService service;@BeforeEach void setup(){service=new CuentaBancariaService(cuentas,empleados,bancos,exports,Clock.fixed(Instant.parse("2026-09-22T12:00:00Z"),ZoneOffset.UTC));}@Test void persisteActivaComoCharUnoYAudita(){Empleado e=empleado();Banco b=banco();when(empleados.findById(1L)).thenReturn(Optional.of(e));when(bancos.findById(2L)).thenReturn(Optional.of(b));when(cuentas.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));service.crear(new CuentaBancariaRequest(1L,2L," 123 ","1"),"admin");ArgumentCaptor<CuentaBancariaEmpleado>c=ArgumentCaptor.forClass(CuentaBancariaEmpleado.class);verify(cuentas).saveAndFlush(c.capture());assertEquals("1",c.getValue().getActiva());assertEquals("123",c.getValue().getNumeroCuenta());assertEquals("admin",c.getValue().getUsuarioCreacion());}@Test void permiteMultiplesCuentasActivas(){Empleado e=empleado();Banco b=banco();when(empleados.findById(1L)).thenReturn(Optional.of(e));when(bancos.findById(2L)).thenReturn(Optional.of(b));when(cuentas.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));service.crear(new CuentaBancariaRequest(1L,2L,"A","1"),"admin");service.crear(new CuentaBancariaRequest(1L,2L,"B","1"),"admin");verify(cuentas,times(2)).saveAndFlush(any());verify(cuentas,never()).findAll();}private Banco banco(){Banco b=mock(Banco.class);when(b.getId()).thenReturn(2L);when(b.getNombre()).thenReturn("Banco");return b;}private Empleado empleado(){Empleado e=mock(Empleado.class);Persona p=mock(Persona.class);when(e.getId()).thenReturn(1L);when(e.getPersona()).thenReturn(p);when(p.getNombre()).thenReturn("Ana");when(p.getApellido()).thenReturn("López");return e;}}
